 function graph(){const members=interactionPassages(),qs=groupQuestions();if(!members.length){status('先加载原文或讲解，再查看这组内容的关系');return}const root='reading-context',nodes=[{id:root,label:'当前这组内容',kind:'source',level:0}],edges=[],seen=new Set([root]);for(const p of members){nodes.push({id:p.id,label:outlineFor(p)?.title||p.alt||'内容片段',detail:p.zh||p.en,kind:'source',level:1,passage_id:p.id});seen.add(p.id);edges.push({from:root,to:p.id});for(const s of p.sentences.filter(s=>!s.historical)){nodes.push({id:s.id,label:s.zh||s.en||p.alt||'素材',kind:'source',level:2,passage_id:p.id,sentence_id:s.id});seen.add(s.id);edges.push({from:p.id,to:s.id})}}for(const q of qs){nodes.push({id:q.id,label:q.text,detail:q.answer,kind:'question',level:3,question_id:q.id,passage_id:q.passage_id,sentence_id:q.sentence_id});seen.add(q.id);edges.push({from:q.parent_question_id||q.sentence_id||q.passage_id,to:q.id});for(const id of q.term_ids||[]){const t=state.terms.find(t=>t.id===id);if(!t)continue;if(!seen.has(id)){nodes.push({id,label:t.name,detail:t.definition,kind:'term',level:4,term_id:id});seen.add(id)}edges.push({from:q.id,to:id})}}for(const quiz of state.quizzes.filter(z=>z.question_ids.some(id=>seen.has(id)))){nodes.push({id:quiz.id,label:quiz.prompt,detail:quiz.explanation,kind:'quiz',level:5,quiz_id:quiz.id});for(const id of quiz.question_ids)edges.push({from:id,to:quiz.id})}$('graph-dialog').showModal();ReaderUI.mindmap($('graph-content'),nodes,edges,async n=>{if(n.term_id){study='terms';termOpen.open=n.term_id;renderStudy();document.getElementById(n.term_id)?.scrollIntoView({block:'center'})}else if(n.quiz_id){study='practice';renderStudy();document.querySelector(`[data-quiz-id="${n.quiz_id}"]`)?.scrollIntoView({block:'center'})}else{if(n.question_id)questionOpen.open=n.question_id;await setFocus(n.passage_id,n.sentence_id||null);renderInteraction();if(n.question_id)document.getElementById(n.question_id)?.scrollIntoView({block:'center'})}$('graph-dialog').close()})}
